contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    function run(address recipient, uint bonusAmount) public payable {
        require(address(this).balance >= bonusAmount);
        // First claim for this recipient is expected to succeed and pay 100 wei.
        c.getFirstWithdrawalBonus(recipient);
        uint balanceAfterFirst = address(recipient).balance;
        // A second claim for the same recipient must revert and must not pay more Ether.
        bool secondClaimReverted;
        try c.getFirstWithdrawalBonus(recipient) {
            secondClaimReverted = false;
        } catch {
            secondClaimReverted = true;
        }
        assert(secondClaimReverted && address(recipient).balance == balanceAfterFirst);
    }

    receive() external payable {}
}

